style.css:
/* Starlit Romance — Dark Cosmic Edition */
/* i really want this to be global */

/* swap these colors if you want */
:root {
  --my-black: #090812 !important;
  --my-navy: #11132b !important;
  --my-plum: #291832 !important;
  --my-purple: #a78bfa !important;
  --my-pink: #e9a6cb !important;
  --my-teal: #83d9d5 !important;
  --my-white: #f8efff !important;
  --my-lavender: #cbb7ff !important;
}

/* midnight galaxy backgrounds */
html,
body {
  background-color: var(--my-black) !important;
  color: var(--my-white) !important;
  font-family: "Segoe UI", sans-serif !important;
}

/* dreamy links */
a {
  color: var(--my-lavender) !important;
  transition: all 0.25s ease !important;
}

a:hover {
  color: var(--my-pink) !important;
  text-shadow: 0 0 10px #e9a6cb80 !important;
}

/* elegant text selection */
::selection {
  background: var(--my-purple) !important;
  color: white !important;
}

/* cosmic scrollbar */
::-webkit-scrollbar {
  width: 9px !important;
}

::-webkit-scrollbar-track {
  background: var(--my-black) !important;
}

::-webkit-scrollbar-thumb {
  background: linear-gradient(
    180deg,
    var(--my-purple),
    var(--my-pink),
    var(--my-teal)
  ) !important;
  border-radius: 20px !important;
}

/* soft image edges */
img {
  border-radius: 10px !important;
}

/* elegant buttons */
button {
  border-radius: 12px !important;
}

/* cosmic input fields */
input,
textarea,
select {
  background-color: #171329 !important;
  color: var(--my-white) !important;
  border: 1px solid #a78bfa55 !important;
  border-radius: 10px !important;
}

/* subtle galaxy dividers */
hr {
  border-color: #a78bfa55 !important;
}

/* soft neon hover glow */
button:hover {
  box-shadow: 0 0 12px #e9a6cb35 !important;
}
